package codexworker

import (
	"encoding/json"
	executionbackend "github.com/erranliu/SteerRunner/internal/execution/backend"
)

const ProfileCodecKey = "codex.worker-profile"
const ProfileCodecVersion = 4
const ReadOnlyProfileCodecVersion = 3

func ProfileVersionForMode(mode string) int {
	if mode == "read_only" {
		return ReadOnlyProfileCodecVersion
	}
	return ProfileCodecVersion
}

// ProfileConfig is the entire user-provided Codex input. Native launch settings
// are generated by this adapter and frozen in the existing resource envelope.
type ProfileConfig struct {
	AccessMode      string `json:"access_mode,omitempty"`
	Executable      string `json:"executable"`
	Model           string `json:"model,omitempty"`
	ReasoningEffort string `json:"reasoning_effort,omitempty"`
}

func DecodeProfileConfig(payload []byte) (ProfileConfig, error) {
	var config ProfileConfig
	if err := executionbackend.DecodeStrictJSON(payload, &config, "Codex profile configuration has trailing JSON"); err != nil {
		return ProfileConfig{}, err
	}
	return config, nil
}
func EncodeProfileConfig(config ProfileConfig) ([]byte, error) { return json.Marshal(config) }
